/* @lc app=leetcode id=1563 lang=kotlin */ class Solution { fun stoneGameV(stoneValue: IntArray): Int = stoneValue.size.let { n -> IntArray(n + 1).also { p -> (0 until n).forEach { i -> p[i + 1] = p[i] + stoneValue[i] } }.let { p -> Array(n) { IntArray(n) }.also { dp -> (2..n).forEach { len -> (0..n - len).forEach { i -> (i + len - 1).let { j -> dp[i][j] = (i until j).maxOf { k -> (p[k + 1] - p[i]).let { left -> (p[j + 1] - p[k + 1]).let { right -> if (left < right) left + dp[i][k] else if (right < left) right + dp[k + 1][j] else left + maxOf(dp[i][k], dp[k + 1][j]) } } } } } } }[0][n - 1] } } }